<script lang="ts">
  import { onMount } from 'svelte';
  import { listScenes, type DatasetSummary, type SceneCatalog as SceneCatalogPayload } from './api';
  interface Props { onBrowse: (datasetId: string) => void; }
  let { onBrowse }: Props = $props();
  let catalog = $state<SceneCatalogPayload | null>(null);
  let loading = $state(true), error = $state('');
  let text = $state(''), roomType = $state(''), density = $state(''), metalClass = $state(''), origin = $state(''), includeUnknown = $state(true);
  let minTotal = $state(''), minPerM2 = $state(''), minArea = $state(''), maxArea = $state(''), minVisible = $state(''), sort = $state('name');
  const fmt = (v: number | null | undefined, digits = 1) => v == null ? '—' : Number(v).toFixed(digits);
  const pct = (v: number | null | undefined) => v == null ? '—' : `${(Number(v) * 100).toFixed(1)}%`;
  const s = (scene: DatasetSummary) => scene.scene_statistics;
  const densityOrder = ['sparse', 'moderate', 'dense', 'unknown'];
  async function load() { loading = true; error = ''; try { catalog = await listScenes({ text, room_type: roomType, density_class: density, metal_class: metalClass, origin, include_unknown: String(includeUnknown), min_total_objects: minTotal, min_objects_per_m2: minPerM2, min_area_m2: minArea, max_area_m2: maxArea, min_visible_objects: minVisible, sort }); } catch (cause) { error = cause instanceof Error ? cause.message : String(cause); } finally { loading = false; } }
  function chooseDensity(value: string) { density = density === value ? '' : value; void load(); }
  function sparseFirst() { density = 'sparse'; includeUnknown = false; sort = 'sparse'; void load(); }
  function reset() { text = ''; roomType = ''; density = ''; metalClass = ''; origin = ''; includeUnknown = true; minTotal = ''; minPerM2 = ''; minArea = ''; maxArea = ''; minVisible = ''; sort = 'name'; void load(); }
  onMount(() => { void load(); });
</script>

<main class="scene-catalog">
  <header class="scene-title"><div><h2>Scene catalog</h2><p>공간 면적, object inventory, 면적당 밀도와 camera pose 가시성을 한 번에 비교합니다.</p></div><button onclick={load} disabled={loading}>{loading ? 'Loading…' : 'Refresh'}</button></header>
  {#if catalog}
    <section class="scene-kpis"><div><b>{catalog.total}</b><span>All scenes</span></div><div><b>{catalog.total - (catalog.distribution.unknown ?? 0)}</b><span>Measured scenes</span></div><div><b>{fmt(catalog.medians.room_area_m2)} m²</b><span>Median space</span></div><div><b>{fmt(catalog.medians.total_objects, 0)}</b><span>Median objects</span></div><div><b>{fmt(catalog.medians.objects_per_m2)}</b><span>Nonstructural / m²</span></div><div><b>{fmt(catalog.medians.visible_objects)}</b><span>Visible objects / pose</span></div></section>
    <section class="scene-analytics"><article class="density-distribution"><header><b>Density distribution</b><small>Click a class to filter</small></header><div class="density-bar">{#each densityOrder as key}<button class:active={density === key} class={`density-segment ${key}`} style={`flex:${catalog.distribution[key] ?? 0}`} onclick={() => chooseDensity(key)}>{catalog.distribution[key] ?? 0}</button>{/each}</div><div class="density-legend">{#each densityOrder as key}<button class:active={density === key} class={`density ${key}`} onclick={() => chooseDensity(key)}>{key} <b>{catalog.distribution[key] ?? 0}</b></button>{/each}</div></article><article class="density-scatter"><header><b>How to read this list</b><small>statistics are dataset-level</small></header><p><b>Objects</b> is total / nonstructural inventory. <b>Space</b> is room footprint. <b>Viewpoint richness</b> measures the selected pose median, so a full room with poorly placed views can still be reviewed.</p><p>Legacy datasets without <code>quality/scene_statistics.json</code> remain <b>Unknown</b>; they are not inferred from images.</p></article></section>
  {/if}
  <section class="scene-filters"><label>Search<input bind:value={text} placeholder="scene name" onkeydown={(event) => event.key === 'Enter' && load()} /></label><label>Room<select bind:value={roomType}><option value="">All rooms</option>{#each catalog?.facets.room_types ?? [] as value}<option value={value}>{value}</option>{/each}</select></label><label>Metal mix<select bind:value={metalClass}><option value="">All</option><option value="balanced-metal">Balanced metal</option><option value="metal-rich">Metal rich</option><option value="metal-sparse">Metal sparse</option><option value="unknown">Unknown</option></select></label><label>Origin<select bind:value={origin}><option value="">All origins</option>{#each catalog?.facets.origins ?? [] as value}<option value={value}>{value}</option>{/each}</select></label><label>Objects min<input type="number" min="0" bind:value={minTotal}/></label><label>Objects/m² min<input type="number" min="0" step=".1" bind:value={minPerM2}/></label><label>Space min m²<input type="number" min="0" bind:value={minArea}/></label><label>Space max m²<input type="number" min="0" bind:value={maxArea}/></label><label>Visible min<input type="number" min="0" step=".1" bind:value={minVisible}/></label><label>Sort<select bind:value={sort}><option value="name">Name</option><option value="sparse">Sparse first</option><option value="objects">Most objects</option><option value="density">Highest objects/m²</option><option value="area">Largest space</option><option value="visible">Most visible</option><option value="metal">Highest metallic coverage</option></select></label><label class="check"><input type="checkbox" bind:checked={includeUnknown}/> Include Unknown</label><button class="primary" onclick={load}>Apply</button><button onclick={sparseFirst}>Sparse first</button><button onclick={reset}>Reset</button></section>
  {#if error}<p class="scene-error">{error}</p>{/if}
  <section class="scene-table"><header><span>Scene</span><span>Room / origin</span><span>Inventory</span><span>Space</span><span>Viewpoint richness</span><span>Status</span></header>{#each catalog?.scenes ?? [] as scene}<button class="scene-row" onclick={() => onBrowse(scene.dataset_id)}><span><b>{scene.name}</b><small>{scene.viewpoint_count} viewpoints · {scene.frame_count} frames</small></span><span>{s(scene).room_type ?? 'Unknown'}<small>{scene.primary_origin}</small></span><span>{s(scene).object_count ?? '—'} total · {s(scene).nonstructural_object_count ?? '—'} nonstruct.<small>{fmt(s(scene).nonstructural_objects_per_m2)} objects/m²</small></span><span>{fmt(s(scene).room_area_m2)} m²<small>{s(scene).room_area_m2 == null ? 'footprint unknown' : 'region footprint'}</small></span><span>{fmt(s(scene).selected_visible_object_median)} visible median<small>{pct(s(scene).selected_nonstructural_fraction_median)} nonstructural coverage</small></span><span class={`density ${s(scene).density_class}`}>{s(scene).density_class}<small>{s(scene).metal_class ?? 'unknown'} · {pct(s(scene).high_metallic_valid_pixel_fraction)} metal</small></span></button>{/each}</section>
  {#if !loading && catalog?.filtered === 0}<p class="empty">No scenes match the current filters.</p>{/if}
</main>
